{
  "examples": [
    {
      "question": "Quelle est la somme des années de sortie de tous les albums ?",
      "sql": "SELECT sum(Year) FROM Albums"
    },
    {
      "question": "Quelle est la somme des positions de toutes les chansons dans les listes de morceaux ?",
      "sql": "SELECT sum(Position) FROM Tracklists"
    },
    {
      "question": "Trouvez l'identifiant de l'album et son titre pour l'album qui contient le plus de chansons.",
      "sql": "SELECT T1.AlbumId, T2.Title FROM Tracklists AS T1 JOIN Albums AS T2 ON T1.AlbumId = T2.AId GROUP BY T1.AlbumId ORDER BY COUNT(*) DESC LIMIT 1"
    },
    {
      "question": "Trouvez l'identifiant de la chanson et le titre de la chanson qui apparaît le plus souvent dans les listes de morceaux.",
      "sql": "SELECT T1.SongId, T2.Title FROM Tracklists AS T1 JOIN Songs AS T2 ON T1.SongId = T2.SongId GROUP BY T1.SongId ORDER BY COUNT(*) DESC LIMIT 1"
    },
    {
      "question": "Donnez-moi la position et le titre d'un album correspondant au premier morceau de sa liste.",
      "sql": "SELECT T1.Position, T2.Title FROM Tracklists AS T1 JOIN Albums AS T2 ON T1.AlbumId = T2.AId WHERE T1.Position = 1"
    },
    {
      "question": "Donnez-moi l'identifiant de l'album et son année de sortie pour les albums ayant un premier morceau enregistré.",
      "sql": "SELECT T1.AlbumId, T2.Year FROM Tracklists AS T1 JOIN Albums AS T2 ON T1.AlbumId = T2.AId WHERE T1.Position = 1"
    },
    {
      "question": "Combien de chansons sont associées à chaque instrument ?",
      "sql": "SELECT Instrument, count(*) FROM Instruments GROUP BY Instrument"
    },
    {
      "question": "Combien de chanteurs sont associés à chaque type de voix ?",
      "sql": "SELECT Type, count(*) FROM Vocals GROUP BY Type"
    },
    {
      "question": "Affichez les titres des chansons qui figurent dans au moins une liste de morceaux.",
      "sql": "SELECT Title FROM Songs WHERE SongId IN (SELECT SongId FROM Tracklists)"
    },
    {
      "question": "Affichez les prénoms des membres du groupe qui participent à au moins une représentation.",
      "sql": "SELECT Firstname FROM Band WHERE Id IN (SELECT Bandmate FROM Performance)"
    },
    {
      "question": "Quels sont les identifiants des chansons dont la position dans une liste de morceaux est supérieure à la position moyenne ?",
      "sql": "SELECT T1.SongId FROM Tracklists AS T1 JOIN Songs AS T2 ON T1.SongId = T2.SongId WHERE T1.Position > (SELECT avg(Position) FROM Tracklists)"
    },
    {
      "question": "Quels sont les identifiants des membres du groupe associés à des chansons dont l'identifiant est supérieur à la moyenne des identifiants de chanson ?",
      "sql": "SELECT T1.BandmateId FROM Instruments AS T1 JOIN Band AS T2 ON T1.BandmateId = T2.Id WHERE T1.SongId > (SELECT avg(SongId) FROM Songs)"
    },
    {
      "question": "Listez la position et le titre des chansons placées en première position, classées par titre.",
      "sql": "SELECT T1.Position, T2.Title FROM Tracklists AS T1 JOIN Songs AS T2 ON T1.SongId = T2.SongId WHERE T1.Position = 1 ORDER BY T2.Title"
    },
    {
      "question": "Listez le type de voix et le titre des chansons concernées, classés par titre.",
      "sql": "SELECT T1.Type, T2.Title FROM Vocals AS T1 JOIN Songs AS T2 ON T1.SongId = T2.SongId ORDER BY T2.Title"
    },
    {
      "question": "Trouvez le nombre d'associations instrumentales pour chaque album.",
      "sql": "SELECT count(*), T1.AlbumId FROM Tracklists AS T1 JOIN Songs AS T2 ON T1.SongId = T2.SongId JOIN Instruments AS T3 ON T2.SongId = T3.SongId GROUP BY T1.AlbumId"
    },
    {
      "question": "Trouvez le nombre de chanteurs associés aux chansons de chaque album.",
      "sql": "SELECT count(*), T1.AlbumId FROM Tracklists AS T1 JOIN Songs AS T2 ON T1.SongId = T2.SongId JOIN Vocals AS T3 ON T2.SongId = T3.SongId GROUP BY T1.AlbumId"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont le nom du réseau et l'autorité locale de la station desservie par le train ayant le plus petit identifiant ?",
      "sql": "SELECT T1.network_name, T1.local_authority FROM station AS T1 JOIN route AS T2 ON T1.id = T2.station_id ORDER BY T2.train_id ASC LIMIT 1"
    },
    {
      "question": "Quels sont le nom et la destination du train portant le numéro le plus élevé parmi les trains desservant une station ?",
      "sql": "SELECT T2.name, T2.destination FROM train AS T2 JOIN route AS T1 ON T2.id = T1.train_id ORDER BY T2.train_number DESC LIMIT 1"
    },
    {
      "question": "Quelles stations ont un nom de réseau qui ne correspond à aucune destination de train ?",
      "sql": "SELECT network_name FROM station WHERE network_name NOT IN (SELECT destination FROM train)"
    },
    {
      "question": "Quelles autorités locales ne correspondent à aucune ville de départ de train ?",
      "sql": "SELECT local_authority FROM station WHERE local_authority NOT IN (SELECT origin FROM train)"
    },
    {
      "question": "Quel est le nom du réseau de la station, parmi celles desservies par le train portant le plus petit numéro, qui a l'identifiant de station le plus élevé ?",
      "sql": "SELECT T3.network_name FROM train AS T1 JOIN route AS T2 ON T1.id = T2.train_id JOIN station AS T3 ON T2.station_id = T3.id WHERE T1.train_number = (SELECT MIN(train_number) FROM train) ORDER BY T3.id DESC LIMIT 1"
    },
    {
      "question": "Quelle est l'autorité locale de la première station desservie par le train portant le plus petit numéro ?",
      "sql": "SELECT T3.local_authority FROM train AS T1 JOIN route AS T2 ON T1.id = T2.train_id JOIN station AS T3 ON T2.station_id = T3.id WHERE T1.train_number = (SELECT MIN(train_number) FROM train) ORDER BY T3.id ASC LIMIT 1"
    },
    {
      "question": "Quelle est l'autorité locale de la station numéro 2 desservie par le train numéro 1 ?",
      "sql": "SELECT T2.local_authority FROM route AS T1 JOIN station AS T2 ON T1.station_id = T2.id WHERE T1.train_id = 1 AND T1.station_id = 2"
    },
    {
      "question": "Quels services sont proposés à la station numéro 1 sur le trajet du train numéro 1 ?",
      "sql": "SELECT T2.services FROM route AS T1 JOIN station AS T2 ON T1.station_id = T2.id WHERE T1.station_id = 1 AND T1.train_id = 1"
    },
    {
      "question": "Quel est le total des précipitations relevées lors des jours ayant la température minimale la plus basse ?",
      "sql": "SELECT sum(T1.precipitation) FROM weekly_weather AS T1 JOIN station AS T2 ON T1.station_id = T2.id WHERE T1.low_temperature = (SELECT low_temperature FROM weekly_weather ORDER BY low_temperature ASC LIMIT 1)"
    },
    {
      "question": "Quel est le total de la vitesse du vent relevée lors des jours ayant les précipitations les plus élevées ?",
      "sql": "SELECT sum(T1.wind_speed_mph) FROM weekly_weather AS T1 JOIN station AS T2 ON T1.station_id = T2.id WHERE T1.precipitation = (SELECT precipitation FROM weekly_weather ORDER BY precipitation DESC LIMIT 1)"
    },
    {
      "question": "Quelle quantité de précipitations a été enregistrée le lundi à la station numéro 1 ?",
      "sql": "SELECT precipitation FROM weekly_weather WHERE station_id = 1 AND day_of_week = 'Monday'"
    },
    {
      "question": "Quelle est la destination des trains qui partent de Chennai ?",
      "sql": "SELECT destination FROM train WHERE origin = 'Chennai'"
    },
    {
      "question": "Affichez les noms de réseau et les autorités locales des stations desservies par au moins deux trajets.",
      "sql": "SELECT T1.network_name, T1.local_authority FROM station AS T1 JOIN route AS T2 ON T1.id = T2.station_id GROUP BY T1.id HAVING count(*) >= 2"
    },
    {
      "question": "Affichez le nom et la destination des trains desservant au moins deux stations.",
      "sql": "SELECT T1.name, T1.destination FROM train AS T1 JOIN route AS T2 ON T1.id = T2.train_id GROUP BY T1.id HAVING count(*) >= 2"
    },
    {
      "question": "Quels sont les noms des trains desservant la station dont le réseau s'appelle Amersham ?",
      "sql": "SELECT DISTINCT T1.name FROM train AS T1 JOIN route AS T2 ON T1.id = T2.train_id JOIN station AS T3 ON T2.station_id = T3.id WHERE T3.network_name = 'Amersham'"
    },
    {
      "question": "Quelles sont les destinations des trains desservant une station située sous l'autorité locale de Watford ?",
      "sql": "SELECT DISTINCT T1.destination FROM train AS T1 JOIN route AS T2 ON T1.id = T2.train_id JOIN station AS T3 ON T2.station_id = T3.id WHERE T3.local_authority = 'Watford'"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont les différents pays représentés parmi les participants ?",
      "sql": "SELECT DISTINCT country FROM attendee"
    },
    {
      "question": "Quelles sont les différentes catégories d'événements organisés ?",
      "sql": "SELECT DISTINCT event_category FROM conference_event"
    },
    {
      "question": "Quels événements comportent à la fois une session animée par Claire Martin et une session animée par Nicolas Perrin ?",
      "sql": "SELECT DISTINCT T1.event_title FROM conference_event AS T1 JOIN event_session AS T2 ON T2.event_id = T1.event_id JOIN event_session AS T3 ON T3.event_id = T1.event_id WHERE T2.speaker_name = 'Claire Martin' AND T3.speaker_name = 'Nicolas Perrin'"
    },
    {
      "question": "Quels événements proposent à la fois une session plénière et un atelier ?",
      "sql": "SELECT DISTINCT T1.event_title FROM conference_event AS T1 JOIN event_session AS T2 ON T2.event_id = T1.event_id JOIN event_session AS T3 ON T3.event_id = T1.event_id WHERE T2.session_format = 'pleniere' AND T3.session_format = 'atelier'"
    },
    {
      "question": "Quels sont les noms et les niveaux d'accessibilité des salles de type conférence ? Triez-les par leur capacité.",
      "sql": "SELECT room_name, accessibility_level FROM venue_room WHERE room_type = 'conference' ORDER BY capacity"
    },
    {
      "question": "Quels sont les titres et les catégories des événements terminés ? Triez-les par leur affluence prévue.",
      "sql": "SELECT event_title, event_category FROM conference_event WHERE status = 'termine' ORDER BY expected_attendance"
    },
    {
      "question": "Quelle organisation a programmé le plus de sessions ? Trouvez son nom.",
      "sql": "SELECT T1.organization_name FROM organizer AS T1 JOIN conference_event AS T2 ON T1.organizer_id = T2.organizer_id JOIN event_session AS T3 ON T2.event_id = T3.event_id GROUP BY T1.organization_name ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quel participant possède le plus d'inscriptions à des événements de technologie ? Trouvez son nom de famille.",
      "sql": "SELECT T1.last_name FROM attendee AS T1 JOIN event_registration AS T2 ON T1.attendee_id = T2.attendee_id JOIN conference_event AS T3 ON T2.event_id = T3.event_id WHERE T3.event_category = 'technologie' GROUP BY T1.first_name, T1.last_name ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Pour chaque organisation, combien d'événements organise-t-elle, classés du plus grand au plus petit nombre ?",
      "sql": "SELECT count(*), T1.organization_name FROM organizer AS T1 JOIN conference_event AS T2 ON T1.organizer_id = T2.organizer_id GROUP BY T1.organization_name ORDER BY count(*) DESC"
    },
    {
      "question": "Pour chaque événement, combien de participants y sont inscrits, classés du plus grand au plus petit nombre ?",
      "sql": "SELECT count(*), T1.event_title FROM conference_event AS T1 JOIN event_registration AS T2 ON T1.event_id = T2.event_id GROUP BY T1.event_title ORDER BY count(*) DESC"
    },
    {
      "question": "Quels sont les titres et les dates de début des événements organisés dans le secteur technologique ?",
      "sql": "SELECT T1.event_title, T1.start_date FROM conference_event AS T1 JOIN organizer AS T2 ON T1.organizer_id = T2.organizer_id WHERE T2.sector = 'technologie'"
    },
    {
      "question": "Quels sont les titres et les intervenants des sessions qui se déroulent dans un auditorium ?",
      "sql": "SELECT T1.session_title, T1.speaker_name FROM event_session AS T1 JOIN venue_room AS T2 ON T1.room_id = T2.room_id WHERE T2.room_type = 'auditorium'"
    },
    {
      "question": "Affichez les 3 premiers types de salles, triés par capacité moyenne décroissante.",
      "sql": "SELECT room_type FROM venue_room GROUP BY room_type ORDER BY avg(capacity) DESC LIMIT 3"
    },
    {
      "question": "Affichez les 3 premières catégories d'événements, triées par affluence moyenne prévue décroissante.",
      "sql": "SELECT event_category FROM conference_event GROUP BY event_category ORDER BY avg(expected_attendance) DESC LIMIT 3"
    },
    {
      "question": "Quel est le titre de l'événement dont l'affluence prévue est la plus faible ?",
      "sql": "SELECT event_title FROM conference_event WHERE expected_attendance = (SELECT MIN(expected_attendance) FROM conference_event)"
    },
    {
      "question": "Quel est le nom de la salle ayant la plus petite capacité ?",
      "sql": "SELECT room_name FROM venue_room WHERE capacity = (SELECT MIN(capacity) FROM venue_room)"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quel est le montant total versé aux producteurs ?",
      "sql": "SELECT SUM(amount_eur) FROM payout"
    },
    {
      "question": "Quelle quantité totale de produits a été réceptionnée ?",
      "sql": "SELECT SUM(quantity_kg) FROM intake"
    },
    {
      "question": "Quels sont les noms des parcelles associées aux cultures récoltées ?",
      "sql": "SELECT T2.label FROM cultivation AS T1 JOIN parcel AS T2 ON T1.parcel_id = T2.parcel_id WHERE T1.status = 'recolte'"
    },
    {
      "question": "Quels exploitants possèdent des cultures récoltées ?",
      "sql": "SELECT T2.full_name FROM cultivation AS T1 JOIN grower AS T2 ON T1.grower_id = T2.grower_id WHERE T1.status = 'recolte'"
    },
    {
      "question": "Quel exploitant a reçu le paiement le plus élevé ?",
      "sql": "SELECT T2.full_name FROM payout AS T1 JOIN grower AS T2 ON T1.grower_id = T2.grower_id ORDER BY T1.amount_eur DESC LIMIT 1"
    },
    {
      "question": "Quelle est la date du paiement correspondant à la plus grande quantité réceptionnée ?",
      "sql": "SELECT T1.paid_on FROM payout AS T1 JOIN intake AS T2 ON T1.intake_id = T2.intake_id ORDER BY T2.quantity_kg DESC LIMIT 1"
    },
    {
      "question": "Quelles sont les cultures de Claire Martin, classées selon le montant total de leurs paiements ?",
      "sql": "SELECT DISTINCT T1.crop_name, SUM(T5.amount_eur) FROM cultivation AS T1 JOIN parcel AS T2 ON T1.parcel_id = T2.parcel_id JOIN grower AS T3 ON T1.grower_id = T3.grower_id JOIN intake AS T4 ON T4.cultivation_id = T1.cultivation_id JOIN payout AS T5 ON T5.intake_id = T4.intake_id WHERE T3.full_name = 'Claire Martin' GROUP BY T1.crop_name ORDER BY SUM(T5.amount_eur) DESC"
    },
    {
      "question": "Quelles parcelles de Nadia Robert et quelles quantités réceptionnées leur sont associées, par ordre décroissant ?",
      "sql": "SELECT DISTINCT T2.label, SUM(T4.quantity_kg) FROM parcel AS T1 JOIN grower AS T2 ON T1.grower_id = T2.grower_id JOIN cultivation AS T3 ON T3.parcel_id = T1.parcel_id JOIN intake AS T4 ON T4.cultivation_id = T3.cultivation_id JOIN payout AS T5 ON T5.intake_id = T4.intake_id WHERE T2.full_name = 'Nadia Robert' GROUP BY T2.label ORDER BY SUM(T4.quantity_kg) DESC"
    },
    {
      "question": "Affichez les noms des parcelles et le nombre de cultures associées à chacune.",
      "sql": "SELECT T1.label, COUNT(*) FROM parcel AS T1 JOIN cultivation AS T2 ON T1.parcel_id = T2.parcel_id GROUP BY T1.parcel_id"
    },
    {
      "question": "Affichez le nom de chaque exploitant et le nombre de réceptions qui lui sont attribuées.",
      "sql": "SELECT T1.full_name, COUNT(*) FROM grower AS T1 JOIN intake AS T2 ON T1.grower_id = T2.grower_id GROUP BY T1.grower_id"
    },
    {
      "question": "Trouvez les cultures dont le rendement prévu moyen dépasse 8 000 kilogrammes.",
      "sql": "SELECT crop_name FROM cultivation GROUP BY crop_name HAVING AVG(expected_yield_kg) > 8000"
    },
    {
      "question": "Quels statuts de culture correspondent à un rendement prévu moyen supérieur à 8 000 kilogrammes ?",
      "sql": "SELECT status FROM cultivation GROUP BY status HAVING AVG(expected_yield_kg) > 8000"
    },
    {
      "question": "Affichez les trois catégories de sol ayant la plus grande superficie moyenne.",
      "sql": "SELECT soil_class FROM parcel GROUP BY soil_class ORDER BY AVG(hectares) DESC LIMIT 3"
    },
    {
      "question": "Affichez les trois cultures dont le rendement prévu moyen est le plus élevé.",
      "sql": "SELECT crop_name FROM cultivation GROUP BY crop_name ORDER BY AVG(expected_yield_kg) DESC LIMIT 3"
    },
    {
      "question": "Quels types de culture ont un prix moyen au kilogramme inférieur à 1 euro ?",
      "sql": "SELECT T1.crop_name FROM cultivation AS T1 JOIN intake AS T2 ON T1.cultivation_id = T2.cultivation_id GROUP BY T1.crop_name HAVING AVG(T2.unit_price) < 1"
    },
    {
      "question": "Quelles parcelles ont une superficie moyenne inférieure à 10 hectares parmi leurs cultures enregistrées ?",
      "sql": "SELECT T1.label FROM parcel AS T1 JOIN cultivation AS T2 ON T1.parcel_id = T2.parcel_id GROUP BY T1.label HAVING AVG(T1.hectares) < 10"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quels sont les modes de paiement et les codes des lots associés à chaque bulletin de salaire ?",
      "sql": "SELECT T1.payment_method, T2.batch_code FROM salary_statement AS T1 JOIN payroll_batch AS T2 ON T1.payroll_batch_id = T2.payroll_batch_id"
    },
    {
      "question": "Quels sont les montants nets et les codes des lots de paie correspondants ?",
      "sql": "SELECT T1.net_amount, T2.batch_code FROM salary_statement AS T1 JOIN payroll_batch AS T2 ON T1.payroll_batch_id = T2.payroll_batch_id"
    },
    {
      "question": "Quel est le montant total des lignes correspondant au salaire de base ?",
      "sql": "SELECT sum(line_amount) FROM pay_line WHERE earning_catalog_id = 1"
    },
    {
      "question": "Quel est le montant net total des bulletins payés par virement bancaire ?",
      "sql": "SELECT sum(net_amount) FROM salary_statement WHERE payment_method = 'bank_transfer'"
    },
    {
      "question": "Pour quel élément de rémunération compte-t-on les lignes de salaire associées, et combien y en a-t-il ?",
      "sql": "SELECT DISTINCT COUNT(T1.pay_line_id), T2.earning_catalog_id FROM pay_line AS T1 JOIN earning_catalog AS T2 ON T1.earning_catalog_id = T2.earning_catalog_id JOIN salary_statement AS T3 ON T1.salary_statement_id = T3.salary_statement_id WHERE T2.earning_code = 'BASE' GROUP BY T2.earning_catalog_id"
    },
    {
      "question": "Combien de bulletins sont associés au cycle de janvier 2024, et quel est l'identifiant de ce cycle ?",
      "sql": "SELECT DISTINCT COUNT(T1.salary_statement_id), T3.pay_cycle_id FROM salary_statement AS T1 JOIN payroll_batch AS T2 ON T1.payroll_batch_id = T2.payroll_batch_id JOIN pay_cycle AS T3 ON T2.pay_cycle_id = T3.pay_cycle_id WHERE T3.cycle_label = '2024-01' GROUP BY T3.pay_cycle_id"
    },
    {
      "question": "Pour chaque unité, quel est le salaire mensuel de base maximal et quel intitulé de poste lui est associé ?",
      "sql": "SELECT T2.unit_name, max(T1.base_monthly), T1.job_title FROM staff_member AS T1 JOIN org_unit AS T2 ON T1.org_unit_id = T2.org_unit_id GROUP BY T2.unit_name"
    },
    {
      "question": "Pour chaque type de rémunération, quel est le montant de ligne le plus élevé et quel est son code ?",
      "sql": "SELECT T2.earning_name, max(T1.line_amount), T2.earning_code FROM pay_line AS T1 JOIN earning_catalog AS T2 ON T1.earning_catalog_id = T2.earning_catalog_id GROUP BY T2.earning_name"
    },
    {
      "question": "Quel statut de cycle de paie apparaît le plus souvent ?",
      "sql": "SELECT cycle_status FROM pay_cycle GROUP BY cycle_status ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quel type de contrat concerne le plus grand nombre de membres du personnel ?",
      "sql": "SELECT contract_type FROM staff_member GROUP BY contract_type ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quel membre du personnel a le salaire mensuel de base le plus élevé ?",
      "sql": "SELECT given_name FROM staff_member WHERE base_monthly = (SELECT MAX(base_monthly) FROM staff_member)"
    },
    {
      "question": "Quel bulletin possède le montant net le plus élevé ?",
      "sql": "SELECT statement_number FROM salary_statement WHERE net_amount = (SELECT MAX(net_amount) FROM salary_statement)"
    },
    {
      "question": "Quels sont les identifiants des bulletins de Camille Bernard ?",
      "sql": "SELECT DISTINCT T1.salary_statement_id FROM salary_statement AS T1 JOIN staff_member AS T2 ON T1.staff_member_id = T2.staff_member_id JOIN payroll_batch AS T3 ON T1.payroll_batch_id = T3.payroll_batch_id WHERE T2.family_name = 'Bernard'"
    },
    {
      "question": "Quels sont les identifiants des lignes correspondant au salaire de base ?",
      "sql": "SELECT DISTINCT T1.pay_line_id FROM pay_line AS T1 JOIN earning_catalog AS T2 ON T1.earning_catalog_id = T2.earning_catalog_id JOIN salary_statement AS T3 ON T1.salary_statement_id = T3.salary_statement_id WHERE T2.earning_code = 'BASE'"
    },
    {
      "question": "Quels sont les identifiants des membres du personnel qui n'ont aucun bulletin de salaire ?",
      "sql": "SELECT staff_member_id FROM staff_member EXCEPT SELECT staff_member_id FROM salary_statement"
    },
    {
      "question": "Quels sont les identifiants des unités qui ne sont associées à aucun membre du personnel ?",
      "sql": "SELECT org_unit_id FROM org_unit EXCEPT SELECT org_unit_id FROM staff_member"
    }
  ]
}
